template <class T1, class D1, class T2, class D2>
bool operator<=(
    const std::unique_ptr<T1, D1>& x,
    const std::unique_ptr<T2, D2>& y) noexcept
{
    // Comparison relies on comparison of underlying raw pointers.
    // Ensure both types yield comparable pointer results (e.g., raw T*)
    return x.get() <= y.get();
}

template <class T, class D>
bool operator<=(const std::unique_ptr<T, D>& x, std::nullptr_t) noexcept
{
    // A unique_ptr is always <= nullptr if its pointer is null
    return x.get() == nullptr;
}

